import{_ as a,o as i,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph for Public Cloud Workloads - Philip Williams, Canonical","description":"","frontmatter":{"title":"Ceph for Public Cloud Workloads - Philip Williams, Canonical","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","分布式存储","公共云","私有云","成本效益"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_for_Public_Cloud_Workloads_-_Philip_Williams_Canonical.md","filePath":"posts/2023/Ceph_for_Public_Cloud_Workloads_-_Philip_Williams_Canonical.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Ceph_for_Public_Cloud_Workloads_-_Philip_Williams_Canonical.md"};function t(n,l,s,h,p,d){return i(),o("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph在公共云工作负载中的应用-公共云与私有云解决方案的经济性比较" tabindex="-1">会议主题：Ceph在公共云工作负载中的应用 - 公共云与私有云解决方案的经济性比较 <a class="header-anchor" href="#会议主题-ceph在公共云工作负载中的应用-公共云与私有云解决方案的经济性比较" aria-label="Permalink to &quot;会议主题：Ceph在公共云工作负载中的应用 - 公共云与私有云解决方案的经济性比较&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主讲人-philip-williams-canonical" tabindex="-1">主讲人：Philip Williams, Canonical <a class="header-anchor" href="#主讲人-philip-williams-canonical" aria-label="Permalink to &quot;主讲人：Philip Williams, Canonical&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>背景介绍</strong>：</p><ul><li>Philip Williams探讨了公共云和私有云在存储成本方面的差异，指出公共云虽然灵活，但对于存储密集型工作负载来说成本可能很高。</li></ul></li><li><p><strong>公共云存储成本分析</strong>：</p><ul><li>以2.5 PB数据在公共云存储5年的成本为例，估算出接近400万美元的费用，强调公共云定价模型的复杂性。</li></ul></li><li><p><strong>私有云解决方案介绍</strong>：</p><ul><li>以Ceph集群为基础，介绍了一种私有云解决方案，该方案在数据中心或合作位置部署，提供了更高的控制和更低的成本。</li></ul></li><li><p><strong>成本比较</strong>：</p><ul><li>通过比较，Philip Williams展示了私有云解决方案在硬件、网络、数据传输和管理服务等方面的成本，总计约85万美元，远低于公共云的成本。</li></ul></li><li><p><strong>优势与控制</strong>：</p><ul><li>强调私有云解决方案在成本控制、数据访问速度和业务数据安全方面的优势，并提到私有云可以作为不同云服务提供商之间的桥梁。</li></ul></li><li><p><strong>未来展望与问题</strong>：</p><ul><li>讨论了未来可能的数据迁移成本，并回答了观众关于硬件交付时间的问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>决定进一步探索和实施私有云解决方案，以降低存储成本并提高数据管理效率。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>研究并制定详细的私有云部署计划。</li><li>与硬件供应商协商，确保硬件交付时间符合项目需求。</li><li>继续监控公共云和私有云的成本变化，以便及时调整策略。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>Philip Williams感谢大家的参与，并鼓励大家就私有云解决方案提出更多问题和建议。</li></ul><p>[会议结束]</p>',14)])])}const c=a(r,[["render",t]]);export{_ as __pageData,c as default};
